-- M5 种子:业务权限码 + 业务角色 + 角色权限绑定(本段由 m5-actor-model.yaml + m2-behavior-model.yaml 生成，勿手改)
-- 编号说明:本件原误编 000005，与同序号的交付内核 DDL(000005_*)同号，goose 收集迁移时直接 panic
-- (duplicate version)，干净库首次部署起不来;种子逻辑上晚于交付内核 DDL，故顺排为 000006。
-- target_ref 取 m5 permissions[].targetRef(即 m2 行为号 FUNC-nn)，不是权限码本身;
-- 运行期 internal/service/seed.go 的 syncM5Authorization 走同一口径，两边互为幂等重复。

-- 角色(m5 roles[])

-- 权限码(m5 permissions[]，权限名取 m2 行为名)

-- 角色权限绑定(m5 roles[].permissions)

-- +goose Down
DELETE FROM sys_role_permission WHERE role_id IN (SELECT id FROM sys_role WHERE code LIKE '%-ROLE-%');
DELETE FROM sys_role WHERE code LIKE '%-ROLE-%' AND code <> 'admin';
DELETE FROM sys_role_permission WHERE permission_id IN (SELECT id FROM sys_permission WHERE code LIKE 'PERM-FUNC-%');
DELETE FROM sys_permission WHERE code LIKE 'PERM-FUNC-%';
